 window.oopProductTitle=(p,lang)=>{if(lang==='en')return englishTitles143[String(p.id)]||p.name;let index=ids.indexOf(String(p.id));const ambiguous=window.oopAmbiguousNames?.has(p.name);if(index<0&&!ambiguous&&window.oopTitleNameIndex) index=window.oopTitleNameIndex[p.name]??-1;const exact=ambiguous?-1:exactNames.indexOf(p.name);return (index>=0&&rows[lang]?.[index])||(exact>=0&&exactRows[lang]?.[exact])||p.name};
 window.oopBuildTitleNameIndex=(products)=>{const byId=new Map(products.map(p=>[String(p.id),p.name]));const names=Object.create(null),stems=new Map();for(const p of products){if(!p.sourcePath)continue;const stem=p.sourcePath.replace(/-\d+\.html(?:[?#].*)?$/,'');if(!stems.has(p.name))stems.set(p.name,new Set());stems.get(p.name).add(stem)}window.oopAmbiguousNames=new Set([...stems].filter(([,paths])=>paths.size>1).map(([name])=>name));ids.forEach((id,i)=>{const name=byId.get(id);if(name&&!window.oopAmbiguousNames.has(name)&&names[name]===undefined)names[name]=i});window.oopTitleNameIndex=names};
